FftPitchCore::PlayMode AudioPlayer::Fft_mode(uint8_t value)
{
    static constexpr FftPitchCore::PlayMode modes[] = {FftPitchCore::PlayMode::OnceForward, FftPitchCore::PlayMode::OnceReverse, FftPitchCore::PlayMode::LoopForward, FftPitchCore::PlayMode::LoopForwardReverse, FftPitchCore::PlayMode::LoopReverseForward, FftPitchCore::PlayMode::LoopReverse};
    return modes[value];
}

int16_t AudioPlayer::Read_fft_source(void *context, uint32_t position)
{
    AudioPlayer &player = *static_cast<AudioPlayer *>(context);
    if (player.LS_flag)
    {
        const uint32_t index = position % LS_buffer_dim;
        if (player.Live_Sampler->first_write_flag && static_cast<int>(index) > player.Live_Sampler->Q_sample)
        {
            return 0; // Never expose unrecorded RAM during the first fill or after erase.
        }
        return player.FIFO[index];
    }
    if (player.source_now.storage == Psram)
    {
        const uint32_t index = position - player.source_now.first_sample;
        return index < player.source_now.samples && player.source_now.psram_ptr != nullptr ? player.source_now.psram_ptr[index] : 0;
    }
    for (uint8_t bank = 0; bank < 2; ++bank)
    {
        if (position >= player.fft_cache_first[bank] && position - player.fft_cache_first[bank] < player.fft_cache_count[bank])
        {
            player.fft_cache_recent = bank;
            return player.fft_read_cache[bank][position - player.fft_cache_first[bank]];
        }
    }
    const uint8_t bank = player.fft_cache_recent ^ 1u;
    player.fft_cache_recent = bank;
    player.fft_cache_first[bank] = position & ~255u;
    player.fft_cache_count[bank] = std::min<uint32_t>(256u, player.fft_core.RegionEnd() - player.fft_cache_first[bank]);
    player.Read_samples(player.fft_read_cache[bank], player.fft_cache_first[bank], player.fft_cache_count[bank]);
    return player.fft_read_cache[bank][position - player.fft_cache_first[bank]];
}

void AudioPlayer::Configure_fft_live_region(uint8_t value, int &first, int &last)
{
    const bool reverse = value == ONCE_REV || value == LOOP_REV || value == LOOP_REV_FWD;
    const int span = value <= ONCE_REV ? LS_buffer_dim : LS_XY_delta + 1;
    int anchor = LS_XY_lock ? LS_X_sample : Live_Sampler->Q_sample + LS_X_delta + 1;
    anchor = (anchor % LS_buffer_dim + LS_buffer_dim) % LS_buffer_dim;
    if (Live_Sampler->Is_writing() && !reverse && !LS_XY_lock)
    {
        const int required = value >= LOOP_FWD ? std::max<int>(Live_fft_margin, span) : Live_fft_margin;
        const int age = (Live_Sampler->Q_sample + 1 - anchor + LS_buffer_dim) % LS_buffer_dim;
        if (age < required || (Live_Sampler->first_write_flag && anchor > Live_Sampler->Q_sample))
        {
            anchor = (Live_Sampler->Q_sample + 1 - required + LS_buffer_dim) % LS_buffer_dim;
        }
    }
    else if (!LS_XY_lock && reverse)
    {
        anchor = (anchor - 1 + LS_buffer_dim) % LS_buffer_dim;
    }
    first = reverse ? (anchor - span + 1 + LS_buffer_dim) % LS_buffer_dim : anchor;
    last = first + span - 1;
    if (Live_Sampler->first_write_flag && value == ONCE_REV)
    {
        first = 0;
        last = std::min(anchor, Live_Sampler->Q_sample);
    }
    else if (Live_Sampler->first_write_flag && !Live_Sampler->Is_writing() && value == ONCE_FWD)
    {
        first = std::min(first, Live_Sampler->Q_sample);
        last = Live_Sampler->Q_sample;
    }
}

bool AudioPlayer::Prepare_fft_live(void)
{
    if (!LS_flag)
    {
        return true;
    }
    if (Live_Sampler->Q_sample < 0 && !Live_Sampler->Is_writing())
    {
        live_unrecorded_notice = true;
        Finish_block();
        return false;
    }
    if (fft_live_waiting)
    {
        if (Live_Sampler->first_write_flag && Live_Sampler->Q_sample + 1 < static_cast<int>(Live_fft_margin) && Live_Sampler->Is_writing())
        {
            return false;
        }
        if (Live_Sampler->Q_sample < 0)
        {
            live_unrecorded_notice = true;
            if (!Live_Sampler->Is_writing())
            {
                Finish_block();
            }
            return false;
        }
        Configure_fft_live_region(fft_mode_wait, A_Flash_sample, B_Flash_sample);
        const bool unavailable_loop = fft_mode_wait >= LOOP_FWD && Live_Sampler->first_write_flag && B_Flash_sample > Live_Sampler->Q_sample;
        const int age = (Live_Sampler->Q_sample + 1 - A_Flash_sample + LS_buffer_dim) % LS_buffer_dim;
        const bool forward_not_ready = fft_mode_wait == ONCE_FWD && Live_Sampler->Is_writing() && (age < static_cast<int>(Live_fft_margin) || (Live_Sampler->first_write_flag && A_Flash_sample > Live_Sampler->Q_sample));
        if (B_Flash_sample - A_Flash_sample + 1 < 100 || unavailable_loop || forward_not_ready)
        {
            if (!Live_Sampler->Is_writing())
            {
                live_unrecorded_notice = true;
                Finish_block();
            }
            return false;
        }
        fft_live_waiting = false;
        fft_core.StartNote(nullptr, B_Flash_sample + 1u, pitch, 1.0f);
        fft_core.SetSampleReader(Read_fft_source, this);
        fft_core.SetRegion(A_Flash_sample, B_Flash_sample + 1u, delta_Noclick >= 2 ? delta_Noclick : 0);
        fft_live_follow = fft_mode_wait == ONCE_FWD && Live_Sampler->Is_writing();
        fft_core.SetMode(fft_live_follow ? FftPitchCore::PlayMode::LoopForward : Fft_mode(fft_mode_wait));
        if (fft_live_follow)
        {
            fft_core.SetRegion(A_Flash_sample, B_Flash_sample + 1u, 0);
        }
    }
    if (fft_live_follow && !Live_Sampler->Is_writing())
    {
        const uint32_t position = fft_core.Transport();
        const uint32_t remaining = (Live_Sampler->Q_sample + LS_buffer_dim - position % LS_buffer_dim) % LS_buffer_dim + 1u;
        fft_core.FinishForwardAt(position + remaining);
        fft_live_follow = false;
    }
    return true;
}

void AudioPlayer::Start_fft(void)
{
    Update_pitch();
    fft_cache_first[0] = fft_cache_first[1] = UINT32_MAX;
    fft_cache_count[0] = fft_cache_count[1] = 0;
    fft_live_follow = false;
    fft_live_restart = false;
    fft_live_waiting = LS_flag;
    if (LS_flag)
    {
        Prepare_fft_live();
        return;
    }
    fft_core.StartNote(nullptr, B_Flash_sample + 1u, pitch, 1.0f);
    fft_core.SetSampleReader(Read_fft_source, this);
    fft_core.SetRegion(A_Flash_sample, B_Flash_sample + 1u, delta_Noclick >= 2 ? delta_Noclick : 0);
    fft_core.SetMode(Fft_mode(fft_mode_wait));
}

void AudioPlayer::Update_fft(void)
{
#ifdef __IMXRT1062__
    const uint32_t timing_begin = micros();
    const bool timing_start = fft_core.GeneratedHops() == 0;
#endif
    audio_block_t *left = allocate();
    audio_block_t *right = allocate();
    if (left == nullptr || right == nullptr)
    {
        if (left != nullptr)
        {
            release(left);
        }
        if (right != nullptr)
        {
            release(right);
        }
        return;
    }
    // The outgoing voice occupies its slot through this final ramp; no second FFT is started in this block.
    const bool replace = warmup_for_play_again_flag || restart_flag;
    bool live_restart = fft_live_restart;
    bool source_ready = Prepare_fft_live();
    if (pitch_tune_flag && !replace)
    {
        pitch_tune = pitch_tune_wait;
        pitch_tune_flag = false;
    }
    if (pitch_bend_flag)
    {
        pitch_bend = pitch_bend_wait;
        pitch_bend_flag = false;
    }
    if (vibrato_flag)
    {
        vibrato_array_element_float += VIBRATO_STEP;
        const uint8_t element = static_cast<uint8_t>(vibrato_array_element_float) % 32;
        *vibrato_array_last_element_ptr = element;
        pitch_vibrato = 1.0f + (vibrato_array_ptr[element] - 1.0f) * modulation_depth;
    }
    Update_pitch();
    fft_core.SetPitch(pitch);
    if (main_settings_editing_flag && !replace)
    {
        if (LS_flag)
        {
            fft_mode_wait = fft_mode_edit;
            Configure_fft_live_region(fft_mode_edit, A_Flash_sample_E, B_Flash_sample_E);
            if (!source_ready || B_Flash_sample_E - A_Flash_sample_E + 1 < 100 || (fft_mode_edit >= LOOP_FWD && Live_Sampler->first_write_flag && B_Flash_sample_E > Live_Sampler->Q_sample))
            {
                fft_live_restart = true;
                main_settings_editing_flag = false;
            }
            fft_live_follow = false;
        }
        if (main_settings_editing_flag)
        {
            fft_live_follow = LS_flag && fft_mode_edit == ONCE_FWD && Live_Sampler->Is_writing();
            fft_core.SetRegion(A_Flash_sample_E, B_Flash_sample_E + 1u, fft_live_follow ? 0 : (delta_Noclick_E >= 2 ? delta_Noclick_E : 0));
            fft_core.SetMode(fft_live_follow ? FftPitchCore::PlayMode::LoopForward : Fft_mode(fft_mode_edit));
            A_Flash_sample = A_Flash_sample_E;
            B_Flash_sample = B_Flash_sample_E;
            mode_player = mode_player_E;
            delta_Noclick = delta_Noclick_E;
            use_Wavetable = use_Wavetable_E;
            Wavetable_ptr = Wavetable_E_ptr;
            Noclick_ptr = Noclick_E_ptr;
            tables_bank_mask = tables_bank_mask_E;
            pitch_limit = pitch_limit_E;
            fft_cache_first[0] = fft_cache_first[1] = UINT32_MAX;
            fft_cache_count[0] = fft_cache_count[1] = 0;
            main_settings_editing_flag = false;
        }
    }
    live_restart = live_restart || fft_live_restart;
    if (volume_gain_warmup_flag)
    {
        volume_gain_warmup_flag = false;
        volume_flag = true;
    }
    if (pan_gain_warmup_flag)
    {
        pan_gain_warmup_flag = false;
        pan_int = pan_int_wait;
        K_pan_gain_L = (pan_gain_L_wait - pan_gain_L) / SAMPLES_VOLUME;
        K_pan_gain_R = (pan_gain_R_wait - pan_gain_R) / SAMPLES_VOLUME;
        JP0 = samples_counter + SAMPLES_VOLUME;
        pan_flag = true;
    }
    if (set_effects_flag)
    {
        resolution_flag = resolution_flag_wait;
        K_resolution_step = K_resolution_step_wait;
        downsampling_flag = downsampling_flag_wait;
        downsampling = downsampling_wait;
        set_effects_flag = false;
    }
    bool did_prepare = false;
    if (source_ready && fft_core.GeneratedHops() == 0 && !replace && !live_restart)
    {
        did_prepare = true;
        source_ready = fft_core.PrepareStartStep();
        if (source_ready && ((audio_update_cycle & 1u) != (identity & 1u) || fft_first_frame_cycle == audio_update_cycle))
        {
            source_ready = false;
        }
        if (source_ready)
        {
            fft_first_frame_cycle = audio_update_cycle;
        }
    }
    (void)did_prepare; // Host shim omits hardware timing.
    for (uint32_t sample = 0; sample < AUDIO_BLOCK_SAMPLES; ++sample)
    {
        if (volume_flag)
        {
            Update_volume_gain();
        }
        if (pan_flag)
        {
            Update_pan_gain();
        }
        ADSR_gain = source_ready || !isPoweredOn() ? ADSR->Get_gain() : 0.0f;
        const int16_t rendered = source_ready ? fft_core.Render() : 0;
        const float value = rendered * volume_gain * velocity_gain * ADSR_gain;
        block[sample] = Lilla_saturate16(static_cast<int32_t>(value));
        if (replace || live_restart)
        {
            block[sample] = block[sample] * static_cast<float>(AUDIO_BLOCK_SAMPLES - 1u - sample) / (AUDIO_BLOCK_SAMPLES - 1u);
        }
        if (downsampling_flag)
        {
            if ((sliding + sample) % downsampling == 0)
            {
                stored_sample = block[sample];
            }
            else
            {
                block[sample] = stored_sample;
            }
        }
        if (resolution_flag)
        {
            const float reduced = ceilf(fabsf(block[sample]) / K_resolution_step) * K_resolution_step;
            block[sample] = Lilla_saturate16(static_cast<int32_t>(block[sample] < 0 ? -reduced : reduced));
        }
        ++samples_counter;
    }
    a_first_sample = fft_core.Transport();
    if (downsampling_flag)
    {
        sliding = (sliding + AUDIO_BLOCK_SAMPLES) % downsampling;
    }
    tone_filter.Process(block, AUDIO_BLOCK_SAMPLES, pitch, tone_filter_level & 0x7f, AUDIO_SAMPLE_RATE_EXACT);
    if (VCF_connect)
    {
        if (VCF_modulated)
        {
            LFO.Update();
        }
        if (VCF_modulated || VCF_pivot_steps > 0)
        {
            Send_LFO_to_VCF();
        }
        else
        {
            VCF.LFO_connect = false;
        }
        VCF.Update();
    }
    for (uint32_t sample = 0; sample < AUDIO_BLOCK_SAMPLES; ++sample)
    {
        left->data[sample] = Lilla_saturate16(static_cast<int32_t>(pan_gain_L * block[sample]));
        right->data[sample] = Lilla_saturate16(static_cast<int32_t>(pan_gain_R * block[sample]));
    }
#ifdef __IMXRT1062__
    if (source_ready || did_prepare)
    {
        const uint32_t elapsed = micros() - timing_begin;
        if (timing_start)
        {
            fft_start_max_us = std::max(fft_start_max_us, elapsed);
            fft_starts += source_ready ? 1u : 0u;
        }
        else
        {
            fft_run_max_us = std::max(fft_run_max_us, elapsed);
        }
    }
#endif
    rendered_block_valid = true;
    transmit(left, 0);
    transmit(right, 1);
    release(left);
    release(right);
    if (replace)
    {
        warmup_for_play_again_flag = false;
        restart_flag = false;
        main_settings_editing_flag = false;
        Start_playing();
    }
    else if (live_restart)
    {
        fft_live_restart = false;
        fft_live_waiting = true;
    }
    else if ((source_ready && !fft_core.IsActive()) || Is_finishing() || (ADSR_gain < 0.0001f && ADSR->Get_phase() > 0))
    {
        state = PlayerState::Idle;
        Close_source();
        My_LED(false);
    }
}
